mapper.select:
SELECT r.resume_sq AS freelancerSq, r.user_sq AS userSq, u.user_nm AS name, r.resume_ttl AS jobTitle, COALESCE( ( SELECT FLOOR(SUM(TIMESTAMPDIFF(MONTH, c.career_start_dt, COALESCE(c.career_end_dt, CURDATE()))) / 12) FROM TBL_RESUME_CAREER_S c WHERE c.resume_sq = r.resume_sq ), 0 ) AS experienceYears, CONCAT('/api/v1/files/', p.file_sq) AS profileImageUrl, r.resume_greeting_txt AS summary, a.address AS address, a.detail_address AS detailAddress, a.sigungu AS sigungu FROM TBL_RESUME_M r
INNER JOIN ( SELECT user_sq, MAX(resume_sq) AS max_resume_sq FROM TBL_RESUME_M WHERE (resume_is_deleted_yn = 'N' OR resume_is_deleted_yn IS NULL) GROUP BY user_sq ) latest_r ON r.resume_sq = latest_r.max_resume_sq
INNER JOIN TBL_USER_M u ON r.user_sq = u.user_sq LEFT JOIN tbl_user_profile_image_s p ON u.user_sq = p.user_sq LEFT JOIN tbl_address_s a ON r.address_sq = a.address_sq
AND (u.user_is_deleted_yn = 'N' OR u.user_is_deleted_yn IS NULL) AND (r.resume_is_deleted_yn = 'N' OR r.resume_is_deleted_yn IS NULL) AND r.resume_ttl IS NOT NULL AND TRIM(r.resume_ttl) != ''
AND (
a.area_code_sq = 36110
(a.area_code_sq >= #{code} AND a.area_code_sq < #{code} + 1000)
a.area_code_sq = #{code}
)
AND r.career_code_sq IN
#{item}
AND r.job_status_code_sq IN
#{item}
AND r.resume_sq IN ( SELECT rss.resume_sq FROM TBL_RESUME_SKILL_SEARCH_S rss WHERE rss.skill_tag_sq IN
#{item}
)
AND (u.user_nm LIKE CONCAT('%', #{req.searchKeyword}, '%') OR r.resume_ttl LIKE CONCAT('%', #{req.searchKeyword}, '%'))
ORDER BY r.resume_sq DESC LIMIT #{req.size} OFFSET #{offset}

SELECT COUNT(DISTINCT r.resume_sq) FROM TBL_RESUME_M r INNER JOIN ( SELECT user_sq, MAX(resume_sq) AS max_resume_sq FROM TBL_RESUME_M WHERE (resume_is_deleted_yn = 'N' OR resume_is_deleted_yn IS NULL) GROUP BY user_sq ) latest_r ON r.resume_sq = latest_r.max_resume_sq INNER JOIN TBL_USER_M u ON r.user_sq = u.user_sq
AND (u.user_is_deleted_yn = 'N' OR u.user_is_deleted_yn IS NULL) AND (r.resume_is_deleted_yn = 'N' OR r.resume_is_deleted_yn IS NULL) AND r.resume_ttl IS NOT NULL AND TRIM(r.resume_ttl) != ''
AND COALESCE( ( SELECT FLOOR(SUM(TIMESTAMPDIFF(MONTH, c.career_start_dt, COALESCE(c.career_end_dt, CURDATE()))) / 12) FROM TBL_RESUME_CAREER_S c WHERE c.resume_sq = r.resume_sq ), 0 ) >= #{req.experience}
AND r.resume_sq IN ( SELECT rss.resume_sq FROM TBL_RESUME_SKILL_SEARCH_S rss INNER JOIN TBL_SKILL_TAG_C st ON rss.skill_tag_sq = st.skill_tag_sq WHERE LOWER(st.skill_tag_nm) IN
LOWER(TRIM(#{skill}))
)
